-- CV & Portfolio Builder: manual Supabase SQL Editor setup.
-- Generated by: python tools/build_supabase_setup.py
-- Creates/updates the application tables, RLS, RPCs and private bucket.
-- Run the WHOLE file in the intended project, as the postgres role.
-- This does not deploy the share-media Edge Function or configure OAuth.
-- SQL Editor execution does not record CLI migration history.
begin;

-- ===== 0001_init.sql =====
-- CV & Portfolio Maker — initial schema
--
-- Design notes:
--   * Profiles hold the reusable source of truth for a user's information.
--   * Documents store configuration only (sections, design, share settings),
--     so many CVs/portfolios can reuse one profile with different presentation.
--   * Row Level Security is enabled everywhere. Every policy is explicit.
--   * Public share resolution goes through SECURITY DEFINER functions, so an
--     anonymous viewer can read only publishable content and never the owner's
--     other records.
--   * The service-role key is never needed by the Flutter client.

create extension if not exists "pgcrypto";

-- ----------------------------------------------------------------- profiles
create table if not exists public.profiles (
  id             uuid primary key references auth.users (id) on delete cascade,
  details        jsonb not null default '{}'::jsonb,
  experiences    jsonb not null default '[]'::jsonb,
  education      jsonb not null default '[]'::jsonb,
  skills         jsonb not null default '[]'::jsonb,
  languages      jsonb not null default '[]'::jsonb,
  certificates   jsonb not null default '[]'::jsonb,
  courses        jsonb not null default '[]'::jsonb,
  awards         jsonb not null default '[]'::jsonb,
  volunteer      jsonb not null default '[]'::jsonb,
  publications   jsonb not null default '[]'::jsonb,
  "references"   jsonb not null default '[]'::jsonb,
  projects       jsonb not null default '[]'::jsonb,
  custom_sections jsonb not null default '[]'::jsonb,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

alter table public.profiles enable row level security;

drop policy if exists "profiles are self-service" on public.profiles;
create policy "profiles are self-service"
  on public.profiles
  for all
  using (auth.uid() = id)
  with check (auth.uid() = id);

-- ---------------------------------------------------------------- documents
create table if not exists public.documents (
  id                  uuid primary key default gen_random_uuid(),
  owner_id            uuid not null references auth.users (id) on delete cascade,
  title               text not null check (length(btrim(title)) > 0),
  type                text not null default 'cv'
                        check (type in ('cv', 'portfolio')),
  design              jsonb not null default '{}'::jsonb,
  included_project_ids text[],
  share_mode          text not null default 'privateDraft'
                        check (share_mode in ('privateDraft', 'publicLink',
                                              'restrictedRecipient')),
  published           boolean not null default false,
  public_slug         text unique,
  allow_pdf_download  boolean not null default true,
  is_rtl              boolean not null default false,
  version             integer not null default 1,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

create index if not exists documents_owner_updated_idx
  on public.documents (owner_id, updated_at desc);

create unique index if not exists documents_public_slug_idx
  on public.documents (public_slug)
  where public_slug is not null;

alter table public.documents enable row level security;

drop policy if exists "owners manage their documents" on public.documents;
create policy "owners manage their documents"
  on public.documents
  for all
  using (auth.uid() = owner_id)
  with check (auth.uid() = owner_id);

-- ------------------------------------------------------------ document_shares
create table if not exists public.document_shares (
  id              uuid primary key default gen_random_uuid(),
  document_id     uuid not null references public.documents (id) on delete cascade,
  mode            text not null
                    check (mode in ('publicLink', 'restrictedRecipient')),

  -- High-entropy, unguessable tokens. 32 random bytes, base64url encoded.
  access_token    text unique,
  slug            text unique,
  recipient_label text,
  recipient_email text,
  expires_at      timestamptz,
  revoked_at      timestamptz,
  view_count      integer not null default 0,
  created_at      timestamptz not null default now(),

  -- A public share uses a slug; a restricted share uses a token.
  constraint share_identifier_shape check (
    (mode = 'publicLink'        and slug is not null and access_token is null) or
    (mode = 'restrictedRecipient' and access_token is not null and slug is null)
  )
);

create index if not exists document_shares_document_idx
  on public.document_shares (document_id);
create index if not exists document_shares_token_idx
  on public.document_shares (access_token);

alter table public.document_shares enable row level security;

-- Owners manage shares for documents they own. Note there is deliberately no
-- policy granting anon/public SELECT: anonymous reads happen only through the
-- SECURITY DEFINER functions below, which enforce publication and expiry.
drop policy if exists "owners manage their shares" on public.document_shares;
create policy "owners manage their shares"
  on public.document_shares
  for all
  using (
    exists (
      select 1 from public.documents d
      where d.id = document_shares.document_id
        and d.owner_id = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.documents d
      where d.id = document_shares.document_id
        and d.owner_id = auth.uid()
    )
  );

-- Access must also work when automatic Data API grants are disabled.
-- RLS above continues to enforce ownership for every operation.
grant select, insert, update, delete on public.profiles,
  public.documents, public.document_shares to authenticated;

-- ===== 0002_sharing_functions.sql =====
-- Share resolution and account deletion functions.
--
-- These are SECURITY DEFINER so an anonymous visitor can resolve a share
-- without being granted blanket read access to `documents`, `profiles` or
-- `document_shares`. Each function enforces:
--   * the share exists and matches the identifier,
--   * the share has not been revoked,
--   * the share has not expired,
--   * the document is actually published.
--
-- Critically, a share grants access to ONE document only — never to the
-- owner's other records.

-- ---------------------------------------------------------- token generation
create or replace function public.generate_share_token()
returns text
language sql
volatile
set search_path = public, extensions
as $$
  -- 32 random bytes -> 43 chars of base64url: unguessable and high entropy.
  select rtrim(translate(encode(gen_random_bytes(32), 'base64'), '+/', '-_'), '=')
$$;

-- ------------------------------------------------------------ slug resolution
create or replace function public.resolve_share_by_slug(p_slug text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_share    public.document_shares%rowtype;
  v_document public.documents%rowtype;
  v_profile  public.profiles%rowtype;
begin
  select * into v_share
    from public.document_shares
   where slug = p_slug
   limit 1;

  if not found then
    return null;
  end if;

  -- Revoked or expired shares are denied here, server-side.
  if v_share.revoked_at is not null then
    return null;
  end if;
  if v_share.expires_at is not null and v_share.expires_at < now() then
    return null;
  end if;

  select * into v_document
    from public.documents
   where id = v_share.document_id;

  if not found or v_document.published is not true then
    return null;
  end if;

  select * into v_profile
    from public.profiles
   where id = v_document.owner_id;

  -- Only the fields needed to render the published page are returned.
  return jsonb_build_object(
    'document', jsonb_build_object(
      'id',               v_document.id,
      'ownerId',          v_document.owner_id,
      'title',            v_document.title,
      'type',             v_document.type,
      'design',           v_document.design,
      'includedProjectIds', v_document.included_project_ids,
      'shareMode',        v_document.share_mode,
      'published',        v_document.published,
      'publicSlug',       v_document.public_slug,
      'allowPdfDownload', v_document.allow_pdf_download,
      'isRtl',            v_document.is_rtl,
      'version',          v_document.version,
      'updatedAtIso',     v_document.updated_at
    ),
    'profile', jsonb_build_object(
      'id',             v_profile.id,
      'details',        v_profile.details,
      'experiences',    v_profile.experiences,
      'education',      v_profile.education,
      'skills',         v_profile.skills,
      'languages',      v_profile.languages,
      'certificates',   v_profile.certificates,
      'courses',        v_profile.courses,
      'awards',         v_profile.awards,
      'volunteer',      v_profile.volunteer,
      'publications',   v_profile.publications,
      'references',     v_profile.references,
      'projects',       v_profile.projects,
      'customSections', v_profile.custom_sections
    ),
    'shareId', v_share.id
  );
end;
$$;

-- ----------------------------------------------------------- token resolution
create or replace function public.resolve_share_by_token(p_token text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_share public.document_shares%rowtype;
  v_document public.documents%rowtype;
  v_profile public.profiles%rowtype;
begin
  -- Restricted shares have no slug. Resolve the token independently and
  -- enforce publication, expiry and revocation before returning its document.
  select * into v_share from public.document_shares
   where access_token = p_token and mode = 'restrictedRecipient';
  if not found then return null; end if;
  if v_share.revoked_at is not null then return null; end if;
  if v_share.expires_at is not null and v_share.expires_at <= now() then
    return null;
  end if;
  select * into v_document from public.documents where id = v_share.document_id;
  if not found or v_document.published is not true then return null; end if;
  select * into v_profile from public.profiles where id = v_document.owner_id;
  if not found then return null; end if;
  -- Payload helpers are installed by 0004 and extended by 0005.
  return jsonb_build_object(
    'document', public._document_payload(v_document),
    'profile', public._profile_payload(v_profile),
    'shareId', v_share.id
  );
end;
$$;

-- ------------------------------------------------------------- view counting
create or replace function public.record_share_view(p_share_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.document_shares
     set view_count = view_count + 1
   where id = p_share_id;
end;
$$;

-- ----------------------------------------------------------- account deletion
create or replace function public.delete_own_account()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Deleting the auth user cascades to profiles, documents and shares.
  delete from auth.users where id = auth.uid();
end;
$$;

-- Anonymous visitors may call the resolvers, but nothing else.
revoke all on function public.resolve_share_by_slug(text)  from public;
revoke all on function public.resolve_share_by_token(text) from public;
revoke all on function public.record_share_view(uuid)      from public;
revoke all on function public.generate_share_token()       from public;
revoke all on function public.delete_own_account()         from public;

grant execute on function public.resolve_share_by_slug(text)  to anon, authenticated;
grant execute on function public.resolve_share_by_token(text) to anon, authenticated;
grant execute on function public.record_share_view(uuid)      to anon, authenticated;
grant execute on function public.generate_share_token()       to authenticated;
grant execute on function public.delete_own_account()         to authenticated;

-- ===== 0003_storage.sql =====
-- Private storage for profile photos and project media.
--
-- The bucket is private by default: nothing is publicly reachable. Objects are
-- written under a `<user-id>/...` prefix and policies authorise by comparing
-- that prefix to `auth.uid()`, so one user can never read another's uploads.

insert into storage.buckets (id, name, public)
values ('document-media', 'document-media', false)
on conflict (id) do nothing;

-- ------------------------------------------------------------------- policies
drop policy if exists "owners read their media" on storage.objects;
create policy "owners read their media"
  on storage.objects
  for select
  to authenticated
  using (
    bucket_id = 'document-media'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists "owners upload their media" on storage.objects;
create policy "owners upload their media"
  on storage.objects
  for insert
  to authenticated
  with check (
    bucket_id = 'document-media'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists "owners update their media" on storage.objects;
create policy "owners update their media"
  on storage.objects
  for update
  to authenticated
  using (
    bucket_id = 'document-media'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists "owners delete their media" on storage.objects;
create policy "owners delete their media"
  on storage.objects
  for delete
  to authenticated
  using (
    bucket_id = 'document-media'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- NOTE: published portfolio images are served through short-lived signed URLs
-- generated for the viewing session, never through public bucket access, so
-- media referenced by a share stays private until it is deliberately shared.

-- ===== 0004_portfolio_access.sql =====
-- Password-protected portfolio access.
--
-- Privacy is enforced in Postgres, not in the client:
--   * The password is hashed with bcrypt (pgcrypto `crypt` + `gen_salt('bf')`)
--     inside a SECURITY DEFINER function, so the plaintext is never stored and
--     never leaves the request that sets it.
--   * `resolve_share_by_slug` is replaced so it REFUSES to return a document
--     that carries a password hash. A visitor must go through
--     `resolve_share_with_password`, which compares the supplied password
--     against the stored hash server-side.
--   * A modified client therefore cannot bypass the check by ignoring a UI
--     toggle: the row is simply not returned without a valid password.

alter table public.documents
  add column if not exists access_password_hash text;

-- ------------------------------------------------------------ set / clear password
create or replace function public.set_portfolio_password(
  p_document_id uuid,
  p_password    text
)
returns void
language plpgsql
security definer
set search_path = public, extensions
as $$
begin
  if p_password is null or length(p_password) < 4 then
    raise exception 'Password must be at least 4 characters';
  end if;

  update public.documents
     set access_password_hash = crypt(p_password, gen_salt('bf')),
         updated_at = now()
   where id = p_document_id
     and owner_id = auth.uid();

  if not found then
    raise exception 'Document not found or not owned by caller';
  end if;
end;
$$;

create or replace function public.clear_portfolio_password(p_document_id uuid)
returns void
language plpgsql
security definer
set search_path = public, extensions
as $$
begin
  update public.documents
     set access_password_hash = null,
         updated_at = now()
   where id = p_document_id
     and owner_id = auth.uid();

  if not found then
    raise exception 'Document not found or not owned by caller';
  end if;
end;
$$;

-- The payload shapes are shared by every resolver, so they live in one place.
create or replace function public._document_payload(v_document public.documents)
returns jsonb
language sql
immutable
as $$
  select jsonb_build_object(
    'id',                 v_document.id,
    'ownerId',            v_document.owner_id,
    'title',              v_document.title,
    'type',               v_document.type,
    'design',             v_document.design,
    'includedProjectIds', v_document.included_project_ids,
    'shareMode',          v_document.share_mode,
    'published',          v_document.published,
    'publicSlug',         v_document.public_slug,
    'allowPdfDownload',   v_document.allow_pdf_download,
    'isRtl',              v_document.is_rtl,
    'version',            v_document.version,
    'updatedAtIso',       v_document.updated_at
  )
$$;

create or replace function public._profile_payload(v_profile public.profiles)
returns jsonb
language sql
immutable
as $$
  select jsonb_build_object(
    'id',             v_profile.id,
    'details',        v_profile.details,
    'experiences',    v_profile.experiences,
    'education',      v_profile.education,
    'skills',         v_profile.skills,
    'languages',      v_profile.languages,
    'certificates',   v_profile.certificates,
    'courses',        v_profile.courses,
    'awards',         v_profile.awards,
    'volunteer',      v_profile.volunteer,
    'publications',   v_profile.publications,
    'references',     v_profile.references,
    'projects',       v_profile.projects,
    'customSections', v_profile.custom_sections
  )
$$;

-- ------------------------------------------------ password-gated resolution
create or replace function public.resolve_share_with_password(
  p_slug     text,
  p_password text
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_share    public.document_shares%rowtype;
  v_document public.documents%rowtype;
  v_profile  public.profiles%rowtype;
begin
  -- SQL NULL comparisons do not evaluate to true; reject absent credentials
  -- before comparing hashes so a direct RPC call cannot bypass the password.
  if p_password is null or p_password = '' then return null; end if;
  select * into v_share
    from public.document_shares
   where slug = p_slug
   limit 1;

  if not found then return null; end if;
  if v_share.revoked_at is not null then return null; end if;
  if v_share.expires_at is not null and v_share.expires_at < now() then
    return null;
  end if;

  select * into v_document from public.documents where id = v_share.document_id;
  if not found or v_document.published is not true then return null; end if;
  if v_document.access_password_hash is null then return null; end if;

  -- The comparison happens here, on the server. A wrong password returns
  -- null exactly like a missing share, so nothing leaks.
  if v_document.access_password_hash is distinct from crypt(p_password, v_document.access_password_hash) then
    return null;
  end if;

  select * into v_profile from public.profiles where id = v_document.owner_id;

  return jsonb_build_object(
    'document', public._document_payload(v_document),
    'profile',  public._profile_payload(v_profile),
    'shareId',  v_share.id
  );
end;
$$;

-- ------------------------------------- plain slug resolution (password-aware)
create or replace function public.resolve_share_by_slug(p_slug text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_share    public.document_shares%rowtype;
  v_document public.documents%rowtype;
  v_profile  public.profiles%rowtype;
begin
  select * into v_share
    from public.document_shares
   where slug = p_slug
   limit 1;

  if not found then return null; end if;
  if v_share.revoked_at is not null then return null; end if;
  if v_share.expires_at is not null and v_share.expires_at < now() then
    return null;
  end if;

  select * into v_document from public.documents where id = v_share.document_id;
  if not found or v_document.published is not true then return null; end if;

  -- Password-protected documents require the dedicated resolver.
  if v_document.access_password_hash is not null then return null; end if;

  select * into v_profile from public.profiles where id = v_document.owner_id;

  return jsonb_build_object(
    'document', public._document_payload(v_document),
    'profile',  public._profile_payload(v_profile),
    'shareId',  v_share.id
  );
end;
$$;

-- --------------------------------------------------------------- permissions
revoke all on function public.set_portfolio_password(uuid, text)      from public;
revoke all on function public.clear_portfolio_password(uuid)          from public;
revoke all on function public.resolve_share_with_password(text, text) from public;
revoke all on function public._document_payload(public.documents)     from public;
revoke all on function public._profile_payload(public.profiles)       from public;

grant execute on function public.set_portfolio_password(uuid, text)      to authenticated;
grant execute on function public.clear_portfolio_password(uuid)          to authenticated;
grant execute on function public.resolve_share_with_password(text, text) to anon, authenticated;

-- ===== 0005_cv_drafts.sql =====
-- CV content is saved per document; Portfolio still uses the live profile.
alter table public.documents add column if not exists profile_snapshot jsonb;

-- Preserve every existing CV before the first independent CV is created.
update public.documents d
   set profile_snapshot = public._profile_payload(p)
  from public.profiles p
 where d.owner_id = p.id and d.type = 'cv' and d.profile_snapshot is null;

create table if not exists public.cv_builder_drafts (
  owner_id uuid not null references auth.users(id) on delete cascade,
  draft_key text not null check (length(draft_key) between 1 and 128),
  payload jsonb not null,
  updated_at timestamptz not null default now(),
  primary key (owner_id, draft_key)
);
alter table public.cv_builder_drafts enable row level security;
drop policy if exists "owners manage their CV drafts" on public.cv_builder_drafts;
create policy "owners manage their CV drafts" on public.cv_builder_drafts
  for all to authenticated using (owner_id = auth.uid())
  with check (owner_id = auth.uid() and payload->'profile'->>'id' = auth.uid()::text);
grant select, insert, update, delete on public.cv_builder_drafts to authenticated;

create or replace function public.capture_legacy_cv_profiles()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.documents set profile_snapshot = public._profile_payload(old)
   where owner_id = old.id and type = 'cv' and profile_snapshot is null;
  return new;
end;
$$;
revoke all on function public.capture_legacy_cv_profiles() from public;
drop trigger if exists capture_legacy_cv_profiles on public.profiles;
create trigger capture_legacy_cv_profiles before update on public.profiles
  for each row execute function public.capture_legacy_cv_profiles();

-- Retain the existing share-authorisation functions. Their document payload
-- now carries the saved content without ever returning a password hash.
create or replace function public._document_payload(v_document public.documents)
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'id', v_document.id, 'ownerId', v_document.owner_id,
    'title', v_document.title, 'type', v_document.type,
    'design', v_document.design, 'profileSnapshot', v_document.profile_snapshot,
    'includedProjectIds', v_document.included_project_ids,
    'shareMode', v_document.share_mode, 'published', v_document.published,
    'publicSlug', v_document.public_slug,
    'allowPdfDownload', v_document.allow_pdf_download,
    'isRtl', v_document.is_rtl, 'version', v_document.version,
    'updatedAtIso', v_document.updated_at
  )
$$;
revoke all on function public._document_payload(public.documents) from public;

notify pgrst, 'reload schema';
commit;

select 'Setup complete' as status, count(*) as application_tables
from information_schema.tables
where table_schema = 'public'
  and table_name in ('profiles', 'documents', 'document_shares', 'cv_builder_drafts');
